local TerrariumKeeper = {}
local PRODUCTS = {
    small_glass_terrar = { name = "Majhen steklen terarij", glassCost = 2, woodCost = 1, time = 3, cost = 45, beauty = 22, prestige = 2, happiness = 1, description = "Majhen terarij za kuščarje in rastline." },
    ornate_wooden_terrarium = { name = "Izrezljan terarij", glassCost = 3, woodCost = 2, marbleCost = 1, time = 6, cost = 130, beauty = 38, prestige = 5, happiness = 2, description = "Izrezljan terarij z marmornim okrasjem." },
    brass_frame_terrarium = { name = "Medeninastični terarij", glassCost = 4, brassCost = 2, woodCost = 1, time = 9, cost = 290, beauty = 50, prestige = 9, happiness = 3, description = "Terarij z medeninastim okvirjem za eksotične vrste." },
    silver_filigree_terrarium = { name = "Srebrnofiligranski terarij", glassCost = 5, silverCost = 2, marbleCost = 1, time = 12, cost = 720, beauty = 64, prestige = 17, happiness = 5, description = "Terarij s srebrnim filigranom za redke vrste." },
    gold_trimmed_terrarium = { name = "Zlatookrasni terarij", glassCost = 6, goldCost = 2, silverCost = 1, marbleCost = 2, jewelCost = 1, time = 16, cost = 1600, beauty = 77, prestige = 27, happiness = 7, description = "Terarij z zlatimi okraski in dragulji za visoke plemiče." },
    royal_grand_terrarium = { name = "Kraljevski veliki terarij", glassCost = 10, goldCost = 3, silverCost = 2, marbleCost = 4, jewelCost = 2, pearlCost = 2, time = 23, cost = 4000, beauty = 93, prestige = 59, happiness = 12, description = "Veliki kraljevski terarij z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    reptile_house = { name = "Terarijska hiša", cost = { gold = 310, wood = 130, stone = 220, glass = 6 }, upkeep = 7, qualityBonus = 5 },
    botanical_salon = { name = "Botanična dvorana", cost = { gold = 1050, wood = 290, stone = 460, glass = 14, marble = 6 }, upkeep = 26, qualityBonus = 18 },
    exotic_atelier = { name = "Egzotični atelje", cost = { gold = 2500, wood = 370, stone = 690, silver = 34, glass = 22 }, upkeep = 63, qualityBonus = 30 },
    royal_botanical_palace = { name = "Kraljevska botanična palača", cost = { gold = 11200, wood = 600, stone = 1050, gold = 72, jewel = 20, glass = 40 }, upkeep = 225, qualityBonus = 55, prestigeBonus = 50 },
}
TerrariumKeeper.glassStock = 18; TerrariumKeeper.woodStock = 14; TerrariumKeeper.brassStock = 8; TerrariumKeeper.marbleStock = 10; TerrariumKeeper.silverStock = 8; TerrariumKeeper.goldStock = 6; TerrariumKeeper.jewelStock = 6; TerrariumKeeper.pearlStock = 4
TerrariumKeeper.productStock = {}; TerrariumKeeper.buildings = {}; TerrariumKeeper.maker = nil; TerrariumKeeper.activeMaking = {}; TerrariumKeeper.totalProducts = 0; TerrariumKeeper.dayTimer = 0
function TerrariumKeeper.init() TerrariumKeeper.glassStock=18; TerrariumKeeper.woodStock=14; TerrariumKeeper.brassStock=8; TerrariumKeeper.marbleStock=10; TerrariumKeeper.silverStock=8; TerrariumKeeper.goldStock=6; TerrariumKeeper.jewelStock=6; TerrariumKeeper.pearlStock=4; TerrariumKeeper.productStock={}; TerrariumKeeper.buildings={}; TerrariumKeeper.maker=nil; TerrariumKeeper.activeMaking={}; TerrariumKeeper.totalProducts=0; TerrariumKeeper.dayTimer=0; print("[TerrariumKeeper] Royal Terrarium Keeper System initialized (6 products, 4 buildings)") end
function TerrariumKeeper.hireMaker(n,s) s=s or math.random(55,90); local c=550+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TerrariumKeeper.maker={name=n or ("Terarijist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Terarijist najet: %s (spretnost: %d)",TerrariumKeeper.maker.name,s),"success") end; return true end
function TerrariumKeeper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TerrariumKeeper.build(id) local ok,e=TerrariumKeeper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TerrariumKeeper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TerrariumKeeper.getQualityBonus() local b=0; for _,bd in ipairs(TerrariumKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TerrariumKeeper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and TerrariumKeeper.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and TerrariumKeeper.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and TerrariumKeeper.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.marbleCost and TerrariumKeeper.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and TerrariumKeeper.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TerrariumKeeper.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TerrariumKeeper.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TerrariumKeeper.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TerrariumKeeper.buildings==0 then return false,"Potrebna terarijska hiša" end; if not TerrariumKeeper.maker then return false,"Potreben terarijist" end; return true end
function TerrariumKeeper.make(pt,qty) qty=qty or 1; local ok,e=TerrariumKeeper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then TerrariumKeeper.glassStock=TerrariumKeeper.glassStock-d.glassCost*qty end; if d.woodCost then TerrariumKeeper.woodStock=TerrariumKeeper.woodStock-d.woodCost*qty end; if d.brassCost then TerrariumKeeper.brassStock=TerrariumKeeper.brassStock-d.brassCost*qty end; if d.marbleCost then TerrariumKeeper.marbleStock=TerrariumKeeper.marbleStock-d.marbleCost*qty end; if d.silverCost then TerrariumKeeper.silverStock=TerrariumKeeper.silverStock-d.silverCost*qty end; if d.goldCost then TerrariumKeeper.goldStock=TerrariumKeeper.goldStock-d.goldCost*qty end; if d.jewelCost then TerrariumKeeper.jewelStock=TerrariumKeeper.jewelStock-d.jewelCost*qty end; if d.pearlCost then TerrariumKeeper.pearlStock=TerrariumKeeper.pearlStock-d.pearlCost*qty end; local t=d.time; if TerrariumKeeper.maker then t=math.max(1,t-math.floor(TerrariumKeeper.maker.skill/12)) end; table.insert(TerrariumKeeper.activeMaking,{id="terrarium_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TerrariumKeeper.completeMaking(m) local q=1.0+(TerrariumKeeper.getQualityBonus()/100); if TerrariumKeeper.maker then q=q+(TerrariumKeeper.maker.skill/150) end; q=math.min(2.5,q); TerrariumKeeper.productStock[m.productType]=(TerrariumKeeper.productStock[m.productType] or 0)+m.quantity; TerrariumKeeper.totalProducts=TerrariumKeeper.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TerrariumKeeper.maker then TerrariumKeeper.maker.itemsMade=TerrariumKeeper.maker.itemsMade+m.quantity; if math.random()<0.25 then TerrariumKeeper.maker.skill=math.min(100,TerrariumKeeper.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Terarij izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"terrarium.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function TerrariumKeeper.update(dt) if not _G.state then return end; TerrariumKeeper.dayTimer=TerrariumKeeper.dayTimer+dt; if TerrariumKeeper.dayTimer>=30 then TerrariumKeeper.dayTimer=0; for i=#TerrariumKeeper.activeMaking,1,-1 do local m=TerrariumKeeper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TerrariumKeeper.completeMaking(m); table.remove(TerrariumKeeper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TerrariumKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TerrariumKeeper.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TerrariumKeeper.getStats() return {glassStock=TerrariumKeeper.glassStock,woodStock=TerrariumKeeper.woodStock,brassStock=TerrariumKeeper.brassStock,marbleStock=TerrariumKeeper.marbleStock,silverStock=TerrariumKeeper.silverStock,goldStock=TerrariumKeeper.goldStock,jewelStock=TerrariumKeeper.jewelStock,pearlStock=TerrariumKeeper.pearlStock,productStock=TerrariumKeeper.productStock,numBuildings=#TerrariumKeeper.buildings,hasMaker=TerrariumKeeper.maker~=nil,makerName=TerrariumKeeper.maker and TerrariumKeeper.maker.name or "—",makerSkill=TerrariumKeeper.maker and TerrariumKeeper.maker.skill or 0,activeMaking=#TerrariumKeeper.activeMaking,totalProducts=TerrariumKeeper.totalProducts} end
return TerrariumKeeper
